#!/usr/bin/env python3
# Some portions generated by Codex. Independent fresh-server means; all requests retained.
import pathlib,json,statistics,math,re
r=pathlib.Path(__file__).resolve().parent;forks=[];metrics=['headersMs','firstRowMs','batchMs','endMs','eofMs']
for d in sorted((r/'runs').glob('matched-*')):
 manifest=json.loads((d/'manifest.json').read_text());assert manifest['status']=='passed',d
 allrows=[]
 for i in range(-20,10):
  x=json.loads((d/f'query-{i}.json').read_text());assert x['rows']==100000 and int(x['terminal']['total-result-count'])==100000
  allrows.append(x)
 rows=allrows[20:];pauses=[float(x) for x in re.findall(r'Pause[^\n]*? ([0-9.]+)ms$',(d/'gc.log').read_text(),re.M)]
 forks.append({'name':d.name,'arm':manifest['arm'],'means':{k:statistics.mean(x[k] for x in rows) for k in metrics},'rangeEofMs':[min(x['eofMs'] for x in rows),max(x['eofMs'] for x in rows)],'byIndex':{k:[x[k] for x in rows] for k in metrics},'coldFirstQuery':{k:allrows[0][k] for k in metrics},'wholeJvmGc':{'count':len(pauses),'totalMs':sum(pauses),'maxMs':max(pauses,default=0)},'heapBeforeMean':statistics.mean(x['before']['heapUsed'] for x in rows),'heapAfterMean':statistics.mean(x['after']['heapUsed'] for x in rows)})
assert len(forks)==8,len(forks)
arms={}
for arm in ['base','depth']:
 ff=[f for f in forks if f['arm']==arm];assert len(ff)==4
 arms[arm]={'means':{k:statistics.mean(f['means'][k] for f in ff) for k in metrics},'forkRangeEofMs':[min(f['means']['eofMs'] for f in ff),max(f['means']['eofMs'] for f in ff)],'measuredIndexMeanEofMs':[statistics.mean(f['byIndex']['eofMs'][i] for f in ff) for i in range(10)]}
blocks=[]
for i in range(0,8,2):
 b={f['arm']:f['means'] for f in forks[i:i+2]};assert len(b)==2
 blocks.append({k:100*(1-b['depth'][k]/b['base'][k]) for k in metrics})
contrasts={}
for k in metrics:
 a,b=arms['base']['means'][k],arms['depth']['means'][k];xs=[math.log(1-x[k]/100) for x in blocks];m=statistics.mean(xs);e=3.1824463*statistics.stdev(xs)/2
 contrasts[k]={'latencyReductionPercent':100*(1-b/a),'throughputChangePercent':100*(a/b-1),'pairedReductionPercent':[x[k] for x in blocks],'descriptive95ReductionInterval':[100*(1-math.exp(m+e)),100*(1-math.exp(m-e))]}
print(json.dumps({'scope':'Actual Workbench HTTP/NDJSON full100k window, not browser render or historical8M fixture','arms':arms,'contrasts':contrasts,'forks':forks},indent=2))
